import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { FlowEventInfo } from "./FlowEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const flowEvent: ConversationEvent = {
  id: "e1",
  conversationEventType: ConversationEventType.FlowStarted,
  name: "flow_started",
  actionText: "",
  flowId: "card_replace",
  stepId: "",
  slotValue: null,
  timestamp: "2020-01-01T00:00:00.000Z",
  originalTimestamp: 0,
  metadata: { parseData: {} },
  __typename: "ConversationEvent",
};

describe("FlowEventInfo", () => {
  it("uses the flow vocabulary", () => {
    renderWithProviders(<FlowEventInfo event={flowEvent} onClose={() => undefined} />);
    expect(screen.getByRole("heading", { name: "Flow event" })).toBeInTheDocument();
  });
});
